class Budget:
    def __init__(self, amount):
        self.balance = amount

    def spend(self, cost):
        if cost <= self.balance:
            self.balance -= cost
            return True
        return False


def budget_report(initial, costs):
    budget = Budget(initial)
    accepted = []
    for cost in costs:
        accepted.append(budget.spend(cost))
    return {"balance": budget.balance, "accepted": accepted}

